from .scfc import Scfc
from robot.api import logger


BBMOD_PRODUCT_CODES = {"ABIA": "473096A", "FBBA": "472182A", "FBBC": "472797A"}


class ScfcTranslator(object):
    def __init__(self, input, output, number_of_bbmods=1, smod_position='LeftSide', hw_version='101', fsp_type=None):
        self.input = input
        self.output = output
        self.number_of_bbmods = number_of_bbmods
        self.smod_position = smod_position
        self.hw_version = hw_version
        self.fsp_type = fsp_type

    def translate(self):
        """Update SCFC and convert it to REL4 if necessary"""
        scfc = Scfc(self.input)
        if self._has_bts_part(scfc):
            self._fix_smod(scfc, self.smod_position)
            self._fix_system_acct_perm(scfc)
            self._enable_bbpooling_for_abic(scfc, self.fsp_type)
            self._enable_apucch_for_abic(scfc, self.fsp_type)
            self._change_pmax_value_for_abic(scfc, self.fsp_type)
            self.translate_fsmr3to4(scfc)
        if self._has_non_sbts_trs_part(scfc):
            self._fix_ethernet_links(scfc, self.hw_version)
            self._update_unit_type(scfc)
            self._fix_l2BurstSize_value(scfc, l2BurstSize_value='1048576', trs_type='non-SBTS')
        if self._has_sbts_trs_part(scfc):
            self._fix_ethlk_connector_label(scfc, eif_number='EIF5')
            self._fix_l2BurstSize_value(scfc, l2BurstSize_value='1048576', trs_type='SBTS')
        scfc.save(self.output)

    def translate_fsmr3to4(self, scfc):
        """Converts the input REL3 SCFC to the output REL4 SCFC"""
        if self._is_rel3_scfc(scfc):
            self._fix_bbmods(scfc, self.number_of_bbmods)
            self._fix_optical_links_in_cablinks(scfc)
            self._fix_optical_links_between_smod_and_bbmod(scfc, self.number_of_bbmods)
            self._fix_emergency_calls_number(scfc)

    def _is_rel3_scfc(self, scfc):
        for bbmod_mo in scfc.find_managed_objects('BBMOD'):
            return not bbmod_mo.find_params('prodCodePlanned')[0].value.startswith('473096A')
        return True

    def _has_bts_part(self, scfc):
        return scfc.find_managed_objects('LNBTS') != []

    @staticmethod
    def _has_non_sbts_trs_part(scfc):
        return scfc.find_managed_objects('FTM') != []

    @staticmethod
    def _has_sbts_trs_part(scfc):
        return scfc.find_managed_objects('TNL') != []

    def _fix_bbmods(self, scfc, number_of_bbmods):
        for bbmod_mo in scfc.find_managed_objects('BBMOD'):
            bbmod_mo.remove()
        for i in range(1, number_of_bbmods + 1):
            self._add_bbmod(scfc, i)

    def _add_bbmod(self, scfc, i):
        cabinet_dist_name = scfc.find_managed_objects('CABINET')[0].dist_name
        bbmod_mo_version = scfc.find_managed_objects('CABINET')[0].version
        bbmod_dist_name = cabinet_dist_name + '/BBMOD-' + str(i)
        bbmod_mo = scfc.add_managed_object(bbmod_dist_name, bbmod_mo_version)
        bbmod_mo.xml.attrib['class'] = 'com.nokia.srbts.eqm:BBMOD'
        bbmod_mo.add_param('eutraSupport', 'false')
        bbmod_mo.add_param('useFullCapacity', 'true')
        bbmod_mo.add_param('geranSupport', 'false')
        bbmod_mo.add_param('prodCodePlanned', '473096A')
        bbmod_mo.add_param('utranSupport', 'false')

    def _fix_smod(self, scfc, smod_position):
        smod_mos = scfc.find_managed_objects('SMOD')
        if len(smod_mos) == 0:
            smod_mo = self._add_smod_mo(scfc)
        else:
            smod_mo = smod_mos[0]
        smod_mo.add_param_or_set_value_in_existing('positionInSubrack', smod_position)
        smod_mo.add_param_or_set_value_in_existing('prodCodePlanned', '473095A')

    def _add_smod_mo(self, scfc):
        cabinet_dist_name = scfc.find_managed_objects('CABINET')[0].dist_name
        smod_mo_version = scfc.find_managed_objects('CABINET')[0].version
        smod_dist_name = cabinet_dist_name + '/SMOD-1'
        smod_mo = scfc.add_managed_object(smod_dist_name, smod_mo_version)
        smod_mo.add_param('climateControlOcxoTemperatureLearning', 'false')
        smod_mo.add_param('eutraSupport', 'true')
        smod_mo.add_param('geranSupport', 'false')
        smod_mo.add_param('utranSupport', 'false')
        smod_mo.add_param('climateControlProfiling', 'Optimized Cooling')
        return smod_mo

    def _fix_optical_links_in_cablinks(self, scfc):
        cell_amount = scfc.count_managed_objects('LNCEL')
        if cell_amount < 9:
            self._fix_optical_links_connected_to_1_bbmod(scfc)
        else:
            self._fix_optical_links_connected_to_3_bbmods(scfc)

    def _fix_optical_links_connected_to_1_bbmod(self, scfc):
        for cablink_mo in scfc.find_managed_objects('CABLINK'):
            self._fix_links_in_cablinks(scfc, cablink_mo, bbmod_id=1)

    def _fix_optical_links_connected_to_3_bbmods(self, scfc):
        for index, cablink_mo in enumerate(scfc.find_managed_objects('CABLINK')):
            self._fix_links_in_cablinks(scfc, cablink_mo, bbmod_id=index)

    def _fix_links_in_cablinks(self, scfc, cablink_mo, bbmod_id):
        cabinet_dist_name = scfc.find_managed_objects('CABINET')[0].dist_name
        smod_path = cabinet_dist_name + '/SMOD-'
        if cablink_mo.find_params('firstEndpointDN')[0].value.startswith(smod_path):
            cablink_mo.remove_param('firstEndpointDN')
            firstEndpointDN_value = str(cabinet_dist_name) + '/BBMOD-' + str(bbmod_id)
            cablink_mo.add_param('firstEndpointDN', firstEndpointDN_value)

    def _fix_optical_links_between_smod_and_bbmod(self, scfc, number_of_bbmods):
        for cablink_smod_bbmod_mo in scfc.find_managed_objects('CABLINK'):
            if cablink_smod_bbmod_mo.find_param('firstEndpointLabel').value == 'QSFP':
                cablink_smod_bbmod_mo.remove()
        for i in range(1, number_of_bbmods + 1):
            self._add_bbmod_smod_cablink(scfc, i)

    def _add_bbmod_smod_cablink(self, scfc, i):
        cablink_mo_last_index = int(scfc.find_managed_objects('CABLINK')[-1].dist_name.split('/')[-1].split('-')[-1])
        cabinet_dist_name = scfc.find_managed_objects('HWTOP')[0].dist_name
        cablink_mo_version = scfc.find_managed_objects('HWTOP')[0].version
        cablink_smod_bbmod_dist_name = cabinet_dist_name + '/CABLINK-' + str(cablink_mo_last_index + 1)
        cablink_smod_bbmod_mo = scfc.add_managed_object(cablink_smod_bbmod_dist_name, cablink_mo_version)
        smod_dist_name = scfc.find_managed_objects('SMOD')[0].dist_name
        cablink_smod_bbmod_mo.add_param('firstEndpointDN', smod_dist_name)
        cablink_smod_bbmod_mo.add_param('firstEndpointPortId', str(i))
        cablink_smod_bbmod_mo.add_param('firstEndpointLabel', 'QSFP')
        cabinet_dist_name = scfc.find_managed_objects('CABINET')[0].dist_name
        bbmod_dist_name = cabinet_dist_name + '/BBMOD-' + str(i)
        cablink_smod_bbmod_mo.add_param('secondEndpointDN', bbmod_dist_name)
        cablink_smod_bbmod_mo.add_param('linkModeConfiguration', 'false')
        cablink_smod_bbmod_mo.add_param('linkModeDC', 'false')
        cablink_smod_bbmod_mo.add_param('linkModeData', 'false')
        cablink_smod_bbmod_mo.add_param('linkModeSynchronization', 'false')
        cablink_smod_bbmod_mo.add_param('secondEndpointLabel', 'QSFP')
        self._fix_cablinks_numeration(scfc)

    def _fix_cablinks_numeration(self, scfc):
        for index, cablink_smod_bbmod_mo in enumerate(scfc.find_managed_objects('CABLINK')):
            cablink_id_string = cablink_smod_bbmod_mo.dist_name.split('/')[-1].split('-')[0] + '-' + str(index + 1)
            cablink_smod_bbmod_mo.xml.attrib['distName'] = (
                '/'.join(cablink_smod_bbmod_mo.dist_name.split('/')[:-1]) + '/' + cablink_id_string
            )

    def _fix_emergency_calls_number(self, scfc):
        if len(scfc.find_managed_objects('FBIP')) > 1 or len(scfc.find_managed_objects('LNCEL')) > 1:
            managed_objects = ['MPUCCH', 'MPUCCH_FDD', 'MPUCCH_TDD']
            for managed_object_name in managed_objects:
                if scfc.find_managed_objects(managed_object_name):
                    for mpucch_mo in scfc.find_managed_objects(managed_object_name):
                        self._fix_param_value_out_of_range(mpucch_mo, 'maxNumRrcEmergency', max_value=420)
                        self._fix_param_value_out_of_range(mpucch_mo, 'maxNumRrc', max_value=420)

    def _fix_param_value_out_of_range(self, mo, param_name, max_value):
        if mo.has_param(param_name):
            param = mo.find_param(param_name)
            current_val = int(param.value)
            if current_val > max_value:
                param.value = max_value

    def _fix_ethernet_links(self, scfc, hw_version):
        for ethlk_mo in scfc.find_managed_objects('ETHLK'):
            ethlk_mo.remove()
        self._add_proper_ethlks_amount(scfc, hw_version)

    def _add_proper_ethlks_amount(self, scfc, hw_version):
        if hw_version in ('X31', '101', '102', '103', '104', '203'):
            for i in range(1, 6):
                self._add_ethlk_mo(scfc, hw_version, i)
        elif hw_version == 'X21':
            for i in range(1, 8):
                self._add_ethlk_mo(scfc, hw_version, i)
        else:
            raise ValueError('Only X21, X31, A101, A102 and A104 hw_versions are supported')

    def _add_ethlk_mo(self, scfc, hw_version, i):
        ethlk_mo_version = scfc.find_managed_objects('FTM')[0].version
        mrbts_dist_name = scfc.find_managed_objects('MRBTS')[0].dist_name
        ethlk_dist_name = mrbts_dist_name + '/NRBTS-1/FTM-1/ETHLK-0-' + str(i)
        ethlk_mo = scfc.add_managed_object(ethlk_dist_name, ethlk_mo_version)
        ethlk_mo.xml.attrib['class'] = 'NOKLTE:ETHLK'
        if hw_version in ('X31', '101', '102', '104') and i == 5:
            ethlk_mo.add_param('administrativeState', 'unlocked')
        elif hw_version == 'X21' and i == 7:
            ethlk_mo.add_param('administrativeState', 'unlocked')
        else:
            ethlk_mo.add_param('administrativeState', 'locked')
        ethlk_mo.add_param('speedAndDuplex', 'AUTODETECT')
        ethlk_mo.add_param('l2ShaperRate', 'RT_LINE_RATE')
        ethlk_mo.add_param('l2IngressRate', 'RT_LINE_RATE')
        ethlk_mo.add_param('acceptableFrameTypes', 'ADMIT_ALL')
        ethlk_mo.add_param('portDefaultPriority', '0')
        ethlk_mo.add_param('portDefaultVlanId', '1')
        ethlk_mo.add_param('l2BurstSize', '0')
        ethlk_mo.add_param('linkOAMEnabled', 'false')
        ethlk_mo.add_param('linkOAMProfile', '')
        ethlk_mo.add_param('flushFdbOnLos', 'false')
        ethlk_mo.add_param('l2ShaperBurstSize', '1M')
        ethlk_mo.add_param('syncEAutoNegMode', 'automatic')
        vlan_list = ethlk_mo.add_list_param('l2VlanIdList')
        vlan_list.add_param('highValue', '4094')
        vlan_list.add_param('lowValue', '2')
        return ethlk_mo

    @staticmethod
    def _update_unit_type(scfc):
        unit_mo = scfc.find_managed_objects('UNIT')[0]
        unit_mo.find_param('unitTypeExpected').value = '473095A'
        if unit_mo.has_param('enableRP301Interface'):
            unit_mo.remove_param('enableRP301Interface')

    @staticmethod
    def _fix_ethlk_connector_label(scfc, eif_number='EIF5'):
        ethlk_mo_amount = scfc.count_managed_objects('ETHLK')
        if ethlk_mo_amount == 1:
            ethlk_mo = scfc.find_managed_objects('ETHLK')[0]
            ethlk_mo.add_param_or_set_value_in_existing('connectorLabel', eif_number)

    def _fix_l2BurstSize_value(self, scfc, l2BurstSize_value='32', trs_type='SBTS', hw_flag='rel4'):
        if trs_type == 'SBTS' or trs_type == '5G':
            l2_burst_size_param_containing_mo = 'BRGPRT'
        else:
            l2_burst_size_param_containing_mo = 'ETHLK'
        for mo_with_l2_burst_size in scfc.find_managed_objects(l2_burst_size_param_containing_mo):
            if hw_flag == 'rel4':
                if mo_with_l2_burst_size.find_param('l2BurstSize').value == '0':
                    mo_with_l2_burst_size.add_param_or_set_value_in_existing('l2BurstSize', l2BurstSize_value)
            else:
                if mo_with_l2_burst_size.find_param('l2BurstSize').value != '0':
                    mo_with_l2_burst_size.add_param_or_set_value_in_existing('l2BurstSize', l2BurstSize_value)

    @staticmethod
    def _fix_system_acct_perm(scfc):
        featcadm_mo = scfc.find_managed_objects('FEATCADM')[0]
        featcadm_mo.add_param_or_set_value_in_existing('systemAcctPermEnable', 'false')

    def _enable_bbpooling_for_abic(self, scfc, fsp_type):
        if fsp_type == 'ABIC':
            lnbts_mo = scfc.find_managed_objects('LNBTS')[0]
            logger.warn('Bbpool activation for ABIC')
            lnbts_mo.add_param_or_set_value_in_existing(param_name='actBbPooling', param_value='true')
            lnbts_mo.add_param_or_set_value_in_existing(param_name='actEnhAcAndGbrServices', param_value='true')
            self._add_bbpool_allocation_mo(scfc)

    @staticmethod
    def _add_bbpool_allocation_mo(scfc):
        if not scfc.find_managed_objects('BBPOOLALLOC'):
            for lncel_mo in scfc.find_managed_objects('LNCEL'):
                dist_name = lncel_mo.dist_name + '/BBPOOLALLOC-0'
                bbpool_mo = scfc.add_managed_object(dist_name=dist_name)
                bbpool_mo.add_param_or_set_value_in_existing(param_name='bbPoolAllocMode', param_value='automatic')

    @staticmethod
    def _enable_apucch_for_abic(scfc, fsp_type):
        if fsp_type == 'ABIC':
            for lncel_fdd_mo in scfc.find_managed_objects('LNCEL_FDD'):
                if lncel_fdd_mo.find_params('actAutoPucchAlloc')[0].value == 'false':
                    lncel_fdd_mo.add_param_or_set_value_in_existing(param_name='actAutoPucchAlloc', param_value='true')
                    dist_name = lncel_fdd_mo.dist_name + '/APUCCH_FDD-0'
                    apucch_fdd_mo = scfc.add_managed_object(dist_name=dist_name)
                    apucch_fdd_mo.add_param_or_set_value_in_existing(param_name='aPucchAddAUeRrHo', param_value='10')
                    apucch_fdd_mo.add_param_or_set_value_in_existing(param_name='aPucchAddAUeTcHo', param_value='15')
                    apucch_fdd_mo.add_param_or_set_value_in_existing(
                        param_name='aPucchMinNumEmergencySessions', param_value='10'
                    )
                    apucch_fdd_mo.add_param_or_set_value_in_existing(param_name='aPucchMinNumRrc', param_value='10')
                    apucch_fdd_mo.add_param_or_set_value_in_existing(
                        param_name='aPucchMinNumRrcNoDrb', param_value='5'
                    )
                    apucch_fdd_mo.add_param_or_set_value_in_existing(
                        param_name='aPucchSrPeriodUpperLimit', param_value='20'
                    )
                    apucch_fdd_mo.add_param_or_set_value_in_existing(param_name='actLbPucchReg', param_value='true')
                    apucch_fdd_mo.add_param_or_set_value_in_existing(
                        param_name='pucchArRateEvalWinLength', param_value='0'
                    )
                    apucch_fdd_mo.add_param_or_set_value_in_existing(
                        param_name='selectPrachRegion', param_value='None'
                    )

    @staticmethod
    def _change_pmax_value_for_abic(scfc, fsp_type):
        if fsp_type == 'ABIC':
            for lncel_mo in scfc.find_managed_objects('LNCEL'):
                if lncel_mo.find_params('pMax')[0].value > 370:
                    lncel_mo.add_param_or_set_value_in_existing(param_name='pMax', param_value='370')


class ScfcTranslatorFsmr4toFsmr3(ScfcTranslator):
    def __init__(self, input, output, ext_bbmods_list=None):
        self.input = input
        self.output = output
        self.number_of_ext_bbmods = len(ext_bbmods_list)
        self.ext_bbmod_types = ext_bbmods_list

    def translate(self):
        """Update SCFC and convert it to REL3 if necessary"""
        scfc = Scfc(self.input)
        if self._has_bts_part(scfc):
            self.translate_fsmr3to4(scfc)
            self._fix_system_acct_perm(scfc)
        scfc.save(self.output)

    def translate_fsmr3to4(self, scfc):
        """Converts the input REL3 SCFC to the output REL4 SCFC"""
        if self._is_rel4_scfc(scfc):
            self._fix_smod(scfc)
            self._fix_bbmods(scfc, self.number_of_ext_bbmods)
            self._fix_optical_links_between_smod_and_bbmod(scfc, self.number_of_ext_bbmods)
            self._fix_remaining_cablinks(scfc)
            if self._has_non_sbts_trs_part(scfc):
                self._fix_ftm_unit_type(scfc)
                self._fix_eth_links(scfc)
                self._fix_l2BurstSize_value(scfc, l2BurstSize_value='0', trs_type='non-SBTS', hw_flag='rel3')
            if self._has_sbts_trs_part(scfc):
                self._fix_ethlk_connector_label(scfc, eif_number='EIF1')
                self._fix_l2BurstSize_value(scfc, l2BurstSize_value='0', trs_type='SBTS', hw_flag='rel3')

    def _fix_ftm_unit_type(self, scfc):
        ftm = scfc.find_managed_objects('UNIT')[0]
        ftm.add_param_or_set_value_in_existing('unitTypeExpected', 'FSM')
        ftm.add_param_or_set_value_in_existing('enableRP301Interface', 'false')

    def _fix_eth_links(self, scfc):
        for eth_link in scfc.find_managed_objects('ETHLK'):
            index = eth_link.dist_name.split('-')[-1]
            if index == '1':
                eth_link.add_param_or_set_value_in_existing('administrativeState', 'unlocked')
                continue
            if index == '2':
                continue
            eth_link.remove()

    def _is_rel4_scfc(self, scfc):
        for smod_mo in scfc.find_managed_objects('SMOD'):
            return not smod_mo.find_params('prodCodePlanned')[0].value.startswith('472181A')
        return False

    def _add_bbmod(self, scfc, i):
        cabinet_dist_name = scfc.find_managed_objects('CABINET')[0].dist_name
        bbmod_mo_version = scfc.find_managed_objects('CABINET')[0].version
        bbmod_dist_name = cabinet_dist_name + '/BBMOD-' + str(i)
        bbmod_mo = scfc.add_managed_object(bbmod_dist_name, bbmod_mo_version)
        bbmod_mo.xml.attrib['class'] = 'com.nokia.srbts.eqm:BBMOD'
        bbmod_mo.add_param('prodCodePlanned', BBMOD_PRODUCT_CODES[self.ext_bbmod_types[i - 1]])
        bbmod_mo.add_param('useFullCapacity', 'true')
        if bbmod_mo.find_param('prodCodePlanned').value == '472797A':
            conn_list = bbmod_mo.add_list_param("srioConnectionList")
            conn_list.add_param("linkId", "4")
            conn_list.add_param("mode", "RF")

    def _fix_smod(self, scfc):
        smod_mo = scfc.find_managed_objects('SMOD')[0]
        smod_mo.add_param_or_set_value_in_existing('prodCodePlanned', '472181A')
        if smod_mo.has_param('positionInSubrack'):
            smod_mo.remove_param('positionInSubrack')

    def _fix_remaining_cablinks(self, scfc):
        i = 1
        bb_index = 1
        for cablink in scfc.find_managed_objects('CABLINK'):
            tmp = cablink.dist_name.split('-')
            tmp[-1] = str(i)
            cablink.dist_name = '-'.join(tmp)
            endpoint = cablink.find_param('firstEndpointDN').value
            if "BBMOD" in endpoint:
                endpoint = endpoint.replace('BBMOD', 'SMOD')
                cablink.add_param_or_set_value_in_existing('firstEndpointDN', endpoint)
            else:
                cablink.add_param_or_set_value_in_existing('firstEndpointPortId', str(bb_index))
                bb_index += 1
            i += 1
